    if (z[1] < minY) minY = z[1];
    if (z[3] > maxY) maxY = z[3];
  }
  List<int> xs = xSet.toList()..sort();
  List<int> ys = ySet.toList()..sort();
  int unionArea = 0;
  for (int i = 0; i < xs.length - 1; i++) {
    for (int j = 0; j < ys.length - 1; j++) {
      bool covered = false;
      for (var z in zones) {
        if (z[0] <= xs[i] && xs[i] < z[2] && z[1] <= ys[j] && ys[j] < z[3]) {
          covered = true;
          break;
        }
      }
      if (covered) {
        unionArea += (xs[i + 1] - xs[i]) * (ys[j + 1] - ys[j]);
      }
    }
  }
  int boundingArea = (maxX - minX) * (maxY - minY);
  int eff = boundingArea == 0 ? 0 : (unionArea * 100 / boundingArea).round();
  return "union: $unionArea, bounding: $boundingArea, efficiency: $eff%";
}

