  int rotateLeft(int value, int shift) {
    shift %= cycleBits;
    value &= limitMask;
    return ((value << shift) | (value >> (cycleBits - shift))) & limitMask;
  }

  int leadingGreenRun(int value) {
    int run = 0;
    while (run < cycleBits && ((value >> run) & 1) == 1) {
      run++;
    }
    return run;
  }

  int transitionCount(int value) {
