    for (int i = 0; i < cycleBits; i++) {
      int current = (value >> i) & 1;
      int next = (value >> ((i + 1) % cycleBits)) & 1;
      if (current != next) {
        count++;
      }
    }
    return count;
  }

  for (final int rawMask in phaseMasks) {
    final int mask = rawMask & limitMask;
    int best = mask;
    int bestRun = -1;
    int bestTransitions = cycleBits + 1;

    for (int shift = 0; shift < cycleBits; shift++) {
      final int rotated = rotateLeft(mask, shift);
      final int run = leadingGreenRun(rotated);
      final int transitions = transitionCount(rotated);

      if (run > bestRun ||
          (run == bestRun && transitions < bestTransitions) ||
          (run == bestRun &&
              transitions == bestTransitions &&
              rotated < best)) {
        best = rotated;
        bestRun = run;
        bestTransitions = transitions;
      }
    }

    result.add(best);
  }

  return result;
}

